pub fn apply_thrice<F: FnMut(i32) -> i32>(mut f: F, start: i32) -> i32 {
    let a = f(start);
    let b = f(a);
    f(b)
}

pub fn run() -> i32 {
    let mut calls = 0;
    let step = |x: i32| {
        calls += 1;
        x + calls
    };
    apply_thrice(step, 0)
}

