    use super::*;
    #[test]
    fn applies_stages_in_order() {
        assert_eq!(run(), 9);
    }

    #[test]
    fn empty_pipeline_is_identity() {
        let p = Pipeline::new();
        assert_eq!(p.run_on(7), 7);
    }
}

